<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth_check.php';
require_once __DIR__ . '/../includes/functions.php';
$pageTitle='Loans';$activePage='loans';$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql="SELECT l.loan_id,m.member_number,m.full_name,b.title,l.date_issued,l.due_date,l.date_returned,CASE WHEN l.date_returned IS NOT NULL THEN 'Returned' WHEN l.due_date<CURRENT_DATE THEN 'Overdue' ELSE 'On loan' END loan_status FROM loans l JOIN members m ON m.member_id=l.member_id JOIN books b ON b.book_id=l.book_id WHERE 1=1";$p=[];if($q!==''){$sql.=' AND (m.full_name LIKE ? OR m.member_number LIKE ? OR b.title LIKE ?)';$l="%$q%";$p=[$l,$l,$l];}if(in_array($status,['Returned','Overdue','On loan'],true)){$sql.=" AND CASE WHEN l.date_returned IS NOT NULL THEN 'Returned' WHEN l.due_date<CURRENT_DATE THEN 'Overdue' ELSE 'On loan' END = ?";$p[]=$status;}$sql.=' ORDER BY l.loan_id DESC';$s=$pdo->prepare($sql);$s->execute($p);$rows=$s->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
<main class="main-content"><header class="topbar"><div><span class="eyebrow">CIRCULATION DESK</span><h1>Loans</h1></div></header><section class="content-card"><?php flash_html();?><div class="section-heading"><div><h2>Borrowing and returns</h2><p>Issue books, monitor due dates and record returns.</p></div><a class="btn" href="issue.php">＋ Issue a book</a></div><form class="search-form"><input name="q" value="<?=e($q)?>" placeholder="Search member or book"><select name="status"><option value="">All statuses</option><?php foreach(['On loan','Overdue','Returned'] as $v):?><option <?=($status===$v?'selected':'')?> value="<?=e($v)?>"><?=e($v)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Member</th><th>Book</th><th>Issued</th><th>Due</th><th>Returned</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><br><small><?=e($r['member_number'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['date_issued'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['date_returned']?:'—')?></td><td><span class="badge-status <?=strtolower(str_replace(' ','-',e($r['loan_status'])))?>"><?=e($r['loan_status'])?></span></td><td><?php if(!$r['date_returned']):?><form method="post" action="return.php" class="inline-form" onsubmit="return confirm('Record this book as returned today?');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="loan_id" value="<?=$r['loan_id']?>"><button class="btn btn-small">Return book</button></form><?php else:?><span class="muted">Completed</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty-state">No loan records found.</td></tr><?php endif;?></tbody></table></div></section></main><?php require __DIR__.'/../includes/footer.php';?>